import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(aLine[i]);
        }

        int splitPoint = n / 2;

        List<Long> leftPart = new ArrayList<>();
        List<Long> rightPart = new ArrayList<>();

        createSums(0, 0, splitPoint, a, m, leftPart);
        createSumsRest(splitPoint, 0, n, a, m, rightPart);

        // Remove duplicates and sort
        TreeSet<Long> uniqueLeftPartSet = new TreeSet<>(leftPart);
        List<Long> uniqueLeftPart = new ArrayList<>(uniqueLeftPartSet);

        long bestTotalSum = 0;

        for (Long val : rightPart) {
            long target = m - val;
            int idx = Collections.binarySearch(uniqueLeftPart, target);
            if (idx < 0) {
                idx = -idx - 1;
            }
            if (idx > 0) {
                long candidate = uniqueLeftPart.get(idx - 1) + val;
                if (candidate > bestTotalSum) {
                    bestTotalSum = candidate;
                }
            }
        }
        System.out.println(bestTotalSum);
    }

    private static void createSums(int i, long total, int limit, long[] a, int m, List<Long> list) {
        if (i == limit) {
            list.add(total);
        } else {
            createSums(i + 1, (total + a[i]) % m, limit, a, m, list);
            createSums(i + 1, total, limit, a, m, list);
        }
    }

    private static void createSumsRest(int i, long total, int n, long[] a, int m, List<Long> list) {
        if (i == n) {
            list.add(total);
        } else {
            createSumsRest(i + 1, (total + a[i]) % m, n, a, m, list);
            createSumsRest(i + 1, total, n, a, m, list);
        }
    }
}
